report.llm_raw:
{
  "summary": [
    {
      "text": "Your website sends enquiries to a contact email on a domain that is about to lapse, and your published head-office details disagree from page to page.",
      "cites": ["f1", "c1"]
    },
    {
      "text": "The award organiser's own hall of fame lists you as a 2025 winner, and Google reviewers give you a 4.7 rating, yet a contractor directory shows a lower grade than your site claims.",
      "cites": ["f8", "f10", "c5"]
    },
    {
      "text": "None of your newest Google reviews carries a reply from you, and your mobile homepage is slow on the phones most enquiries come from.",
      "cites": ["f5", "f7"]
    }
  ],
  "email": {
    "subject": {
      "text": "The domain behind your contact email expires on 2026-12-04",
      "cites": ["f1"]
    },
    "body": [
      {
        "text": "The contact address printed on your website sits on a domain you use, and that registration expires on 2026-12-04. If it lapses, the site's mail routing goes with it and anyone writing to that address is cut off.",
        "cites": ["f1"]
      },
      {
        "text": "Your two websites also give different head-office phone numbers and different enquiry emails, so a customer who finds one page cannot reach the office the other page describes.",
        "cites": ["c1", "c8"]
      },
      {
        "text": "Your Google rating is strong, and a contractor directory still shows a lower grade than your own site claims, which is what a tender panel may read first.",
        "cites": ["f10", "c5"]
      }
    ]
  },
  "titles": [
    {
      "id": "f1",
      "text": "The domain behind your printed contact email expires soon, and your site's mail routing goes with it."
    },
    {
      "id": "f2",
      "text": "Anyone can send email that looks like it comes from your addresses, so a forged invoice can reach your client."
    },
    {
      "id": "f3",
      "text": "Your LinkedIn phone field holds part of your registration number, so a prospect who taps it cannot call you."
    },
    {
      "id": "f4",
      "text": "A contractor directory under your own registration number shows a dummy phone and hides your address."
    },
    {
      "id": "f5",
      "text": "Not one of your newest Google reviews has a reply from you, and the lone negative one sits unanswered."
    },
    {
      "id": "f6",
      "text": "Google reports your robots file as invalid, which weakens the search ranking your site claims for itself."
    },
    {
      "id": "f7",
      "text": "Your mobile homepage is slow to paint while your desktop version is instant, on the device most enquiries come from."
    },
    {
      "id": "c1",
      "text": "Your two websites give different head-office phone numbers, so one set of customers dials a line that may be stale."
    },
    {
      "id": "c2",
      "text": "Your head-office unit number appears three different ways, so couriers and survey teams can arrive at the wrong door."
    },
    {
      "id": "c3",
      "text": "Your branch list differs between your own two sites and a directory, so customers see different offices near them."
    },
    {
      "id": "c4",
      "text": "Your staff count reads three different ways on pages you control, so a bank or a candidate sees three companies."
    },
    {
      "id": "c5",
      "text": "A contractor directory shows a lower grade than your own site claims, which can rule you out of larger tenders."
    },
    {
      "id": "c6",
      "text": "Your completed-project count more than doubles depending on which page a prospect finds first."
    },
    {
      "id": "c7",
      "text": "A job board gives you a foreign legal form, so a customer or bank reads a company unsure of its own name."
    },
    {
      "id": "c8",
      "text": "Your two sites print different head-office emails, and one of them depends on the domain that is lapsing."
    },
    {
      "id": "n1",
      "text": "Worth checking: your only negative Google review carries the same name as one of your own engineers."
    },
    {
      "id": "n2",
      "text": "Worth checking why several of your five-star reviews landed on the same day."
    },
    {
      "id": "n3",
      "text": "A directory snippet attaches a different main phone number to your office; worth checking which line it belongs to."
    },
    {
      "id": "n4",
      "text": "Your revenue figure and an award profile's sales figure read as the same number; worth checking how a reader takes it."
    },
    {
      "id": "n5",
      "text": "Worth knowing that no tender awards, extortion listings or sanctions name you, which is a clean record rather than an achievement."
    },
    {
      "id": "n6",
      "text": "Google Maps sends visitors to one of your domains while your site calls another canonical; worth checking where that link lands."
    }
  ],
  "proof": {
    "id": "f1",
    "why": "The expiry date can be checked in a minute, it is urgent, and renewing the domain still leaves the phone, grade, review and search problems untouched."
  }
}

